// Package cpl is the runtime of CPL code compiled to Go (spec/hosts.md): the values (Int,
// Bytes, List, Option, Result, the standard library's error types), faults, the calling
// context with its call-depth limit, the builtins of the standard library, value text, and
// value JSON. Generated by `cpl build --target go`: do not edit.
//
// CPL Text is a Go string holding valid UTF-8, Bool is bool, and Unit is the empty struct
// Unit. Every value is immutable: a List shares its elements, and appending to a list nothing
// else has grown happens in place.
package cpl

import (
	"bufio"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"math/big"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
	"unicode/utf8"
)

// ===========================================================================
// Int: arbitrary precision, int64 while the value fits
// ===========================================================================

// Int is a CPL Int: an arbitrary-precision integer. A value that fits in an int64 is stored
// inline, so arithmetic on it is a machine operation with an overflow check.
type Int struct {
	s int64
	b *big.Int // non-nil exactly when the value does not fit in an int64; never mutated
}

// I is the Int of an int64.
func I(v int64) Int { return Int{s: v} }

// FromBig is the Int of a big.Int, which it copies.
func FromBig(v *big.Int) Int { return norm(new(big.Int).Set(v)) }

// IntLit is an integer literal of the program.
func IntLit(t string) Int {
	v, ok := ParseInt(t)
	if !ok {
		panic("cpl: an invalid integer literal")
	}
	return v
}

func norm(b *big.Int) Int {
	if b.IsInt64() {
		return Int{s: b.Int64()}
	}
	return Int{b: b}
}

func (a Int) bigv() *big.Int {
	if a.b != nil {
		return a.b
	}
	return big.NewInt(a.s)
}

// Int64 is the value as an int64, when it fits.
func (a Int) Int64() (int64, bool) { return a.s, a.b == nil }

// Big is the value as a new big.Int.
func (a Int) Big() *big.Int { return new(big.Int).Set(a.bigv()) }

func (a Int) String() string {
	if a.b != nil {
		return a.b.String()
	}
	return strconv.FormatInt(a.s, 10)
}

// Sign is -1, 0, or 1.
func (a Int) Sign() int {
	if a.b != nil {
		return a.b.Sign()
	}
	switch {
	case a.s < 0:
		return -1
	case a.s > 0:
		return 1
	}
	return 0
}

// Each operation is small enough for Go to inline where it is used: a machine operation, and
// a call of its arbitrary-precision path only when an operand or the result does not fit in an
// int64 (H4).

func (a Int) Add(b Int) Int {
	if a.b == nil && b.b == nil {
		c := a.s + b.s
		if (c > a.s) == (b.s > 0) {
			return Int{s: c}
		}
	}
	return a.addBig(b)
}

func (a Int) addBig(b Int) Int { return norm(new(big.Int).Add(a.bigv(), b.bigv())) }

func (a Int) Sub(b Int) Int {
	if a.b == nil && b.b == nil {
		c := a.s - b.s
		if (c < a.s) == (b.s > 0) {
			return Int{s: c}
		}
	}
	return a.subBig(b)
}

func (a Int) subBig(b Int) Int { return norm(new(big.Int).Sub(a.bigv(), b.bigv())) }

func (a Int) Mul(b Int) Int {
	// operands of 32 bits cannot overflow
	if a.b == nil && b.b == nil && uint64(a.s+1<<31) < 1<<32 && uint64(b.s+1<<31) < 1<<32 {
		return Int{s: a.s * b.s}
	}
	return a.mulWide(b)
}

func (a Int) mulWide(b Int) Int {
	if a.b == nil && b.b == nil {
		x, y := a.s, b.s
		if x == 0 || y == 0 {
			return Int{}
		}
		c := x * y
		if c/y == x && !(x == -1 && y == math.MinInt64) && !(y == -1 && x == math.MinInt64) {
			return Int{s: c}
		}
	}
	return norm(new(big.Int).Mul(a.bigv(), b.bigv()))
}

func (a Int) Neg() Int {
	if a.b == nil && a.s != math.MinInt64 {
		return Int{s: -a.s}
	}
	return a.negBig()
}

func (a Int) negBig() Int { return norm(new(big.Int).Neg(a.bigv())) }

func (a Int) Abs() Int {
	if a.Sign() < 0 {
		return a.Neg()
	}
	return a
}

func (a Int) Cmp(b Int) int {
	if a.b == nil && b.b == nil {
		switch {
		case a.s < b.s:
			return -1
		case a.s > b.s:
			return 1
		}
		return 0
	}
	return a.cmpBig(b)
}

func (a Int) cmpBig(b Int) int { return a.bigv().Cmp(b.bigv()) }

func (a Int) Eq(b Int) bool {
	if a.b == nil && b.b == nil {
		return a.s == b.s
	}
	return a.eqBig(b)
}

// eqBig: a value has one representation, so a small and a big Int differ.
func (a Int) eqBig(b Int) bool { return a.b != nil && b.b != nil && a.b.Cmp(b.b) == 0 }

func (a Int) Ne(b Int) bool { return !a.Eq(b) }

func (a Int) Lt(b Int) bool {
	if a.b == nil && b.b == nil {
		return a.s < b.s
	}
	return a.cmpBig(b) < 0
}

func (a Int) Le(b Int) bool {
	if a.b == nil && b.b == nil {
		return a.s <= b.s
	}
	return a.cmpBig(b) <= 0
}

func (a Int) Gt(b Int) bool {
	if a.b == nil && b.b == nil {
		return a.s > b.s
	}
	return a.cmpBig(b) > 0
}

func (a Int) Ge(b Int) bool {
	if a.b == nil && b.b == nil {
		return a.s >= b.s
	}
	return a.cmpBig(b) >= 0
}

func (a Int) isZero() bool { return a.b == nil && a.s == 0 }

// Div is truncating division (semantics 6.3); division by zero faults, blamed on symbol.
func (a Int) Div(b Int, symbol string) Int {
	if a.b == nil && b.b == nil && b.s != 0 && !(a.s == math.MinInt64 && b.s == -1) {
		return Int{s: a.s / b.s}
	}
	return a.divSlow(b, symbol)
}

func (a Int) divSlow(b Int, symbol string) Int {
	if b.isZero() {
		panic(NewFault("division_by_zero", "", "", symbol, "division by zero"))
	}
	return norm(new(big.Int).Quo(a.bigv(), b.bigv()))
}

// Rem is the remainder of truncating division: it has the dividend's sign.
func (a Int) Rem(b Int, symbol string) Int {
	if a.b == nil && b.b == nil && b.s != 0 && !(a.s == math.MinInt64 && b.s == -1) {
		return Int{s: a.s % b.s}
	}
	return a.remSlow(b, symbol)
}

func (a Int) remSlow(b Int, symbol string) Int {
	if b.isZero() {
		panic(NewFault("division_by_zero", "", "", symbol, "division by zero"))
	}
	return norm(new(big.Int).Rem(a.bigv(), b.bigv()))
}

// ParseInt reads the decimal grammar of parse_int: ("+" | "-")? ASCII_DIGIT+.
func ParseInt(t string) (Int, bool) {
	d := t
	if len(d) > 0 && (d[0] == '+' || d[0] == '-') {
		d = d[1:]
	}
	if len(d) == 0 {
		return Int{}, false
	}
	for i := 0; i < len(d); i++ {
		if d[i] < '0' || d[i] > '9' {
			return Int{}, false
		}
	}
	if len(d) <= 18 {
		v, err := strconv.ParseInt(t, 10, 64)
		if err == nil {
			return Int{s: v}, true
		}
	}
	b, ok := new(big.Int).SetString(t, 10)
	if !ok {
		return Int{}, false
	}
	return norm(b), true
}

// index is the value as a list index or count, when it is one.
func (a Int) index() (int, bool) {
	if a.b == nil && a.s >= 0 && a.s <= math.MaxInt {
		return int(a.s), true
	}
	return 0, false
}

func (a Int) WriteText(sb *TextBuilder) { sb.WriteString(a.String()) }
func (a Int) EqualAny(o any) bool       { b, ok := o.(Int); return ok && a.Eq(b) }
func (a Int) ToJSON() any               { return json.Number(a.String()) }

// ===========================================================================
// Bytes, List, Option, Result, Unit
// ===========================================================================

// Bytes is a CPL Bytes: an immutable byte string.
type Bytes struct{ s string }

// BytesOf is the Bytes of a byte slice, which it copies.
func BytesOf(b []byte) Bytes { return Bytes{string(b)} }

// Slice is a copy of the bytes.
func (b Bytes) Slice() []byte { return []byte(b.s) }
func (b Bytes) Len() int      { return len(b.s) }

func (b Bytes) WriteText(sb *TextBuilder) {
	sb.WriteString("Bytes(\"")
	sb.WriteString(hex.EncodeToString([]byte(b.s)))
	sb.WriteString("\")")
}
func (b Bytes) EqualAny(o any) bool { c, ok := o.(Bytes); return ok && b == c }
func (b Bytes) ToJSON() any {
	return map[string]any{"$type": "Bytes", "hex": hex.EncodeToString([]byte(b.s))}
}

// List is a CPL List: an immutable sequence. The zero value is the empty list.
type List[T any] struct {
	s []T
	// How many elements of s's backing array are claimed, when this list may grow in place;
	// nil for a list that copies on its first append.
	hw *atomic.Int64
}

// ListOf is the list of the given elements, which it copies.
func ListOf[T any](items ...T) List[T] {
	s := make([]T, len(items))
	copy(s, items)
	return List[T]{s: s}
}

// ListLit is a list literal of the program: it keeps the argument slice.
func ListLit[T any](items ...T) List[T] { return List[T]{s: items} }

func (l List[T]) Len() int      { return len(l.s) }
func (l List[T]) At(i int) T    { return l.s[i] }
func (l List[T]) IsEmpty() bool { return len(l.s) == 0 }

// Items is the elements, shared: do not modify them.
func (l List[T]) Items() []T { return l.s[:len(l.s):len(l.s)] }

// ToSlice is a copy of the elements.
func (l List[T]) ToSlice() []T {
	s := make([]T, len(l.s))
	copy(s, l.s)
	return s
}

func grown[T any](l List[T], extra int) List[T] {
	n := len(l.s)
	c := 2 * (n + extra)
	if c < 4 {
		c = 4
	}
	s := make([]T, n+extra, c)
	copy(s, l.s)
	hw := new(atomic.Int64)
	hw.Store(int64(n + extra))
	return List[T]{s, hw}
}

// Push is the list with v appended, in place when no other list has grown this one.
func (l List[T]) Push(v T) List[T] {
	n := len(l.s)
	if l.hw != nil && n < cap(l.s) && l.hw.CompareAndSwap(int64(n), int64(n+1)) {
		s := l.s[:n+1]
		s[n] = v
		return List[T]{s, l.hw}
	}
	g := grown(l, 1)
	g.s[n] = v
	return g
}

// ListConcat is a ++ b, in place when no other list has grown a.
func ListConcat[T any](a, b List[T]) List[T] {
	if len(b.s) == 0 {
		return a
	}
	if len(a.s) == 0 {
		return b
	}
	n, m := len(a.s), len(b.s)
	if a.hw != nil && n+m <= cap(a.s) && a.hw.CompareAndSwap(int64(n), int64(n+m)) {
		s := a.s[:n+m]
		copy(s[n:], b.s)
		return List[T]{s, a.hw}
	}
	g := grown(a, m)
	copy(g.s[n:], b.s)
	return g
}

func ListEq[T any](a, b List[T], eq func(T, T) bool) bool {
	if len(a.s) != len(b.s) {
		return false
	}
	for i := range a.s {
		if !eq(a.s[i], b.s[i]) {
			return false
		}
	}
	return true
}

func (l List[T]) WriteText(sb *TextBuilder) {
	sb.WriteByte('[')
	for i, x := range l.s {
		if i > 0 {
			sb.WriteString(", ")
		}
		WriteText(sb, x)
	}
	sb.WriteByte(']')
}
func (l List[T]) EqualAny(o any) bool {
	m, ok := o.(List[T])
	return ok && ListEq(l, m, Eq[T])
}
func (l List[T]) ToJSON() any {
	out := make([]any, len(l.s))
	for i, x := range l.s {
		out[i] = ToJSON(x)
	}
	return out
}

// Option is a CPL Option: Some(v) or None. The zero value is None.
type Option[T any] struct {
	some bool
	v    T
}

func Some[T any](v T) Option[T] { return Option[T]{true, v} }
func None[T any]() Option[T]    { return Option[T]{} }

func (o Option[T]) IsSome() bool   { return o.some }
func (o Option[T]) IsNone() bool   { return !o.some }
func (o Option[T]) Get() (T, bool) { return o.v, o.some }

// Unwrap is the value of a Some.
func (o Option[T]) Unwrap() T {
	if !o.some {
		panic("cpl: Unwrap of None")
	}
	return o.v
}

func OptionEq[T any](a, b Option[T], eq func(T, T) bool) bool {
	return a.some == b.some && (!a.some || eq(a.v, b.v))
}

func (o Option[T]) WriteText(sb *TextBuilder) {
	if !o.some {
		sb.WriteString("None")
		return
	}
	sb.WriteString("Some(")
	WriteText(sb, o.v)
	sb.WriteByte(')')
}
func (o Option[T]) EqualAny(x any) bool {
	p, ok := x.(Option[T])
	return ok && OptionEq(o, p, Eq[T])
}
func (o Option[T]) ToJSON() any {
	if !o.some {
		return Tagged("Option", "None", nil)
	}
	return Tagged("Option", "Some", []any{ToJSON(o.v)})
}

// Result is a CPL Result: Ok(v) or Err(e).
type Result[T, E any] struct {
	ok bool
	v  T
	e  E
}

func Ok[T, E any](v T) Result[T, E]  { return Result[T, E]{ok: true, v: v} }
func Err[T, E any](e E) Result[T, E] { return Result[T, E]{e: e} }

func (r Result[T, E]) IsOk() bool  { return r.ok }
func (r Result[T, E]) IsErr() bool { return !r.ok }

// Get is the value, the error, and whether the result is Ok.
func (r Result[T, E]) Get() (T, E, bool) { return r.v, r.e, r.ok }

// Unwrap is the value of an Ok.
func (r Result[T, E]) Unwrap() T {
	if !r.ok {
		panic("cpl: Unwrap of Err")
	}
	return r.v
}

// UnwrapErr is the error of an Err.
func (r Result[T, E]) UnwrapErr() E {
	if r.ok {
		panic("cpl: UnwrapErr of Ok")
	}
	return r.e
}

func ResultEq[T, E any](a, b Result[T, E], eqT func(T, T) bool, eqE func(E, E) bool) bool {
	if a.ok != b.ok {
		return false
	}
	if a.ok {
		return eqT(a.v, b.v)
	}
	return eqE(a.e, b.e)
}

func (r Result[T, E]) WriteText(sb *TextBuilder) {
	if r.ok {
		sb.WriteString("Ok(")
		WriteText(sb, r.v)
	} else {
		sb.WriteString("Err(")
		WriteText(sb, r.e)
	}
	sb.WriteByte(')')
}
func (r Result[T, E]) EqualAny(x any) bool {
	p, ok := x.(Result[T, E])
	return ok && ResultEq(r, p, Eq[T], Eq[E])
}
func (r Result[T, E]) ToJSON() any {
	if r.ok {
		return Tagged("Result", "Ok", []any{ToJSON(r.v)})
	}
	return Tagged("Result", "Err", []any{ToJSON(r.e)})
}

// Unit is the CPL Unit.
type Unit struct{}

func (Unit) WriteText(sb *TextBuilder) { sb.WriteString("Unit") }
func (Unit) EqualAny(o any) bool       { _, ok := o.(Unit); return ok }
func (Unit) ToJSON() any               { return map[string]any{"$type": "Unit"} }

// Box is a reference to v: the field of a struct that contains its own type.
func Box[T any](v T) *T { return &v }

// Is reports whether x holds a V: the variant test of an enum.
func Is[V any](x any) bool {
	_, ok := x.(V)
	return ok
}

// ===========================================================================
// The standard library's data types
// ===========================================================================

// ConstraintError is the error of check<R> and of the standard parsers (stdlib 1.5).
type ConstraintError struct {
	TypeName string
	Message  string
}

func (a ConstraintError) Equal(b ConstraintError) bool { return a == b }
func (a ConstraintError) EqualAny(o any) bool {
	b, ok := o.(ConstraintError)
	return ok && a == b
}
func (a ConstraintError) WriteText(sb *TextBuilder) {
	sb.WriteString("ConstraintError { type_name: ")
	sb.WriteString(QuoteText(a.TypeName))
	sb.WriteString(", message: ")
	sb.WriteString(QuoteText(a.Message))
	sb.WriteString(" }")
}
func (a ConstraintError) ToJSON() any {
	return map[string]any{"$type": "ConstraintError", "type_name": a.TypeName, "message": a.Message}
}

// ForeignErrorKind is std.foreign.ForeignErrorKind.
type ForeignErrorKind int

const (
	ForeignErrorKind_Exception ForeignErrorKind = iota
	ForeignErrorKind_InvalidArgument
	ForeignErrorKind_InvalidResult
	ForeignErrorKind_Transport
	ForeignErrorKind_Timeout
	ForeignErrorKind_Cancelled
	ForeignErrorKind_Unavailable
)

var foreignErrorKindNames = [...]string{"Exception", "InvalidArgument", "InvalidResult", "Transport", "Timeout", "Cancelled", "Unavailable"}

func (k ForeignErrorKind) Name() string                  { return foreignErrorKindNames[k] }
func (k ForeignErrorKind) Equal(o ForeignErrorKind) bool { return k == o }
func (k ForeignErrorKind) EqualAny(o any) bool           { b, ok := o.(ForeignErrorKind); return ok && k == b }
func (k ForeignErrorKind) WriteText(sb *TextBuilder)     { sb.WriteString(k.Name()) }
func (k ForeignErrorKind) ToJSON() any                   { return Tagged("std.foreign.ForeignErrorKind", k.Name(), nil) }

// ForeignDetail is std.foreign.ForeignDetail.
type ForeignDetail struct {
	Key   string
	Value string
}

func (a ForeignDetail) Equal(b ForeignDetail) bool { return a == b }
func (a ForeignDetail) EqualAny(o any) bool        { b, ok := o.(ForeignDetail); return ok && a == b }
func (a ForeignDetail) WriteText(sb *TextBuilder) {
	sb.WriteString("ForeignDetail { key: ")
	sb.WriteString(QuoteText(a.Key))
	sb.WriteString(", value: ")
	sb.WriteString(QuoteText(a.Value))
	sb.WriteString(" }")
}
func (a ForeignDetail) ToJSON() any {
	return map[string]any{"$type": "std.foreign.ForeignDetail", "key": a.Key, "value": a.Value}
}

// ForeignError is std.foreign.ForeignError: a foreign failure as a typed CPL error.
type ForeignError struct {
	Kind    ForeignErrorKind
	Message string
	Details List[ForeignDetail]
}

func (a ForeignError) Equal(b ForeignError) bool {
	return a.Kind == b.Kind && a.Message == b.Message && ListEq(a.Details, b.Details, ForeignDetail.Equal)
}
func (a ForeignError) EqualAny(o any) bool { b, ok := o.(ForeignError); return ok && a.Equal(b) }
func (a ForeignError) WriteText(sb *TextBuilder) {
	sb.WriteString("ForeignError { kind: ")
	a.Kind.WriteText(sb)
	sb.WriteString(", message: ")
	sb.WriteString(QuoteText(a.Message))
	sb.WriteString(", details: ")
	a.Details.WriteText(sb)
	sb.WriteString(" }")
}
func (a ForeignError) ToJSON() any {
	return map[string]any{"$type": "std.foreign.ForeignError", "kind": a.Kind.ToJSON(), "message": a.Message, "details": a.Details.ToJSON()}
}

// ===========================================================================
// Values in generic code
// ===========================================================================

// TextBuilder accumulates value text.
type TextBuilder = strings.Builder

// Value is what every generated type, and every runtime type but string and bool, supports.
type Value interface {
	WriteText(sb *TextBuilder)
	EqualAny(o any) bool
	ToJSON() any
}

// Eq is structural equality (semantics 6.5) of two values of a type parameter.
func Eq[T any](a, b T) bool {
	switch x := any(a).(type) {
	case Int:
		return x.Eq(any(b).(Int))
	case bool:
		return x == any(b).(bool)
	case string:
		return x == any(b).(string)
	case Value:
		return x.EqualAny(any(b))
	}
	panic(fmt.Sprintf("cpl: %T is not a CPL value", a))
}

func BoolEq(a, b bool) bool   { return a == b }
func TextEq(a, b string) bool { return a == b }
func BytesEq(a, b Bytes) bool { return a == b }
func UnitEq(a, b Unit) bool   { return true }

// WriteText writes the value text (semantics S40) of v.
func WriteText(sb *TextBuilder, v any) {
	switch x := v.(type) {
	case bool:
		if x {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
	case string:
		sb.WriteString(QuoteText(x))
	case Value:
		x.WriteText(sb)
	default:
		panic(fmt.Sprintf("cpl: %T is not a CPL value", v))
	}
}

// ValueText is CPL literal syntax for v: what check<R> quotes in its error message.
func ValueText(v any) string {
	var sb TextBuilder
	WriteText(&sb, v)
	return sb.String()
}

// QuoteText is a text as a CPL literal, with the grammar's escapes.
func QuoteText(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, c := range s {
		switch {
		case c == '\\':
			sb.WriteString("\\\\")
		case c == '"':
			sb.WriteString("\\\"")
		case c == '\n':
			sb.WriteString("\\n")
		case c == '\r':
			sb.WriteString("\\r")
		case c == '\t':
			sb.WriteString("\\t")
		case c < 0x20 || c == 0x7f:
			fmt.Fprintf(&sb, "\\u{%x}", c)
		default:
			sb.WriteRune(c)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// CheckFailure is check<R>'s error when the predicate of typeName fails on value (6.10).
func CheckFailure[U any](value any, typeName, predicate string) Result[U, ConstraintError] {
	return Err[U](ConstraintError{TypeName: typeName, Message: ValueText(value) + " does not satisfy " + predicate})
}

// ValidText reports whether a string from the host is a CPL Text: valid UTF-8.
func ValidText(s string) bool { return utf8.ValidString(s) }

// ===========================================================================
// Faults and the calling context
// ===========================================================================

// Fault is a fault (semantics 6.7): an execution that cannot continue. Generated code
// panics with a *Fault; the functions a host calls recover it as their error.
type Fault struct {
	// Code is the diagnostic code: contract_violation, assertion_failed, division_by_zero,
	// unresolved_hole, resource_exhaustion, refinement_violation, ...
	Code string
	// ClauseKind is requires, ensures, invariant, or decreases for a contract violation.
	ClauseKind string
	// Clause is the failing clause's text (an assertion's expression, a hole's name).
	Clause string
	// Symbol is the stable identity of the blamed declaration.
	Symbol  string
	Message string
}

func (f *Fault) Error() string { return f.Code + ": " + f.Message }

func NewFault(code, kind, clause, symbol, message string) *Fault {
	return &Fault{Code: code, ClauseKind: kind, Clause: clause, Symbol: symbol, Message: message}
}

func requiresFault(clause, symbol string) *Fault {
	return NewFault("contract_violation", "requires", clause, symbol, "requires clause failed: "+clause)
}

// RefinementFault is the error of an argument that does not satisfy its type (S39).
func RefinementFault(expected, symbol string) *Fault {
	return NewFault("refinement_violation", "", "", symbol, "the value does not satisfy "+expected)
}

// Recover turns a fault into the error of a function a host called, attributed by the call's
// context: defer cpl.Recover(cx, &err).
func Recover(cx *Cx, err *error) {
	if r := recover(); r != nil {
		if f, ok := r.(*Fault); ok {
			cx.Attribute(f)
			*err = f
			return
		}
		panic(r)
	}
}

// MaxCallDepth is the default call-depth limit (semantics S38).
const MaxCallDepth = 10000

type measure struct {
	f   int
	m   Int
	set bool
}

// Cx is the context of one call from the host: the call depth and the measures of the
// active recursive functions (S35). Generated functions take it last.
type Cx struct {
	depth, limit int
	// The activations of functions with a decreases clause, innermost last: the first
	// eight in place, the rest in mspill, so that a call nesting no deeper allocates nothing.
	nmeasures int
	measures  [8]measure
	mspill    []measure
	// The owners of the contract expressions being evaluated, innermost last (S34), stored
	// the same way.
	nclauses int
	clauses  [8]string
	cspill   []string
}

func (cx *Cx) measure(i int) *measure {
	if i < len(cx.measures) {
		return &cx.measures[i]
	}
	return &cx.mspill[i-len(cx.measures)]
}

func NewCx() *Cx { return &Cx{limit: MaxCallDepth} }

// NewCxWithDepth is a context with another call-depth limit.
func NewCxWithDepth(limit int) *Cx { return &Cx{limit: limit} }

// Enter is a function activation (S38).
func (cx *Cx) Enter() {
	cx.depth++
	if cx.depth > cx.limit {
		panic(NewFault("resource_exhaustion", "", "", "", fmt.Sprintf("the call depth limit of %d activations was exceeded", cx.limit)))
	}
}

func (cx *Cx) Leave() { cx.depth-- }

// MeasurePush begins the activation of function f, which has a decreases clause.
func (cx *Cx) MeasurePush(f int) {
	if cx.nmeasures < len(cx.measures) {
		cx.measures[cx.nmeasures] = measure{f: f}
	} else {
		cx.mspill = append(cx.mspill, measure{f: f})
	}
	cx.nmeasures++
}

// MeasureSet checks and records the measure of the current activation of f (S35): it is
// >= 0 and below the measure the nearest enclosing activation of f recorded, if any.
func (cx *Cx) MeasureSet(f int, m Int, clause, symbol string) {
	n := cx.nmeasures
	for i := n - 2; i >= 0; i-- {
		if e := cx.measure(i); e.f == f {
			if e.set && m.Ge(e.m) {
				panic(NewFault("contract_violation", "decreases", clause, symbol, "decreases clause failed: "+clause))
			}
			break
		}
	}
	if m.Sign() < 0 {
		panic(NewFault("contract_violation", "decreases", clause, symbol, "decreases clause failed: "+clause))
	}
	*cx.measure(n - 1) = measure{f: f, m: m, set: true}
}

// MeasurePop ends the activation that began with the last MeasurePush, after its ensures.
func (cx *Cx) MeasurePop() {
	cx.nmeasures--
	if cx.nmeasures >= len(cx.measures) {
		cx.mspill = cx.mspill[:len(cx.mspill)-1]
	}
}

// ClauseEnter begins the evaluation of a contract expression of owner (S34).
func (cx *Cx) ClauseEnter(owner string) {
	if cx.nclauses < len(cx.clauses) {
		cx.clauses[cx.nclauses] = owner
	} else {
		cx.cspill = append(cx.cspill, owner)
	}
	cx.nclauses++
}

// ClauseLeave ends the evaluation of the last contract expression begun.
func (cx *Cx) ClauseLeave() {
	cx.nclauses--
	if cx.nclauses >= len(cx.clauses) {
		cx.cspill = cx.cspill[:len(cx.cspill)-1]
	}
}

// Attribute makes a fault that escaped a contract expression its owner's (S34). A fault ends
// the call, so the innermost expression still being evaluated when it arrives is the one it
// escaped.
func (cx *Cx) Attribute(f *Fault) {
	switch {
	case cx == nil || cx.nclauses == 0:
	case cx.nclauses <= len(cx.clauses):
		f.Symbol = cx.clauses[cx.nclauses-1]
	default:
		f.Symbol = cx.cspill[len(cx.cspill)-1]
	}
}

// ===========================================================================
// Value JSON (toolchain 7.3)
// ===========================================================================

// ToJSON is the value JSON of v, as a tree of encoding/json values.
func ToJSON(v any) any {
	switch x := v.(type) {
	case bool:
		return x
	case string:
		return x
	case Value:
		return x.ToJSON()
	}
	panic(fmt.Sprintf("cpl: %T is not a CPL value", v))
}

// Tagged is the value JSON of an enum variant or a wrapper.
func Tagged(typ, variant string, payload []any) map[string]any {
	m := map[string]any{"$type": typ}
	if variant != "" {
		m["$variant"] = variant
	}
	if payload != nil {
		m["$payload"] = payload
	}
	return m
}

// Untag is the $variant and $payload of a tagged value of typ.
func Untag(j any, typ string) (string, []any, error) {
	m, ok := j.(map[string]any)
	if !ok || m["$type"] != typ {
		return "", nil, errors.New("expected a " + typ)
	}
	v, _ := m["$variant"].(string)
	p, _ := m["$payload"].([]any)
	return v, p, nil
}

// ExpectType checks the $type of a struct's value JSON.
func ExpectType(j any, typ string) error {
	m, ok := j.(map[string]any)
	if !ok || m["$type"] != typ {
		return errors.New("expected a " + typ)
	}
	return nil
}

// Field is a field of a struct's value JSON.
func Field(j any, name string) (any, error) {
	m, _ := j.(map[string]any)
	v, ok := m[name]
	if !ok {
		return nil, errors.New("missing field " + name)
	}
	return v, nil
}

func DecInt(j any) (Int, error) {
	n, ok := j.(json.Number)
	if !ok {
		return Int{}, errors.New("expected an integer")
	}
	v, ok := ParseInt(string(n))
	if !ok {
		return Int{}, errors.New(string(n) + " is not an integer")
	}
	return v, nil
}

func DecBool(j any) (bool, error) {
	b, ok := j.(bool)
	if !ok {
		return false, errors.New("expected a boolean")
	}
	return b, nil
}

func DecText(j any) (string, error) {
	s, ok := j.(string)
	if !ok {
		return "", errors.New("expected a text")
	}
	return s, nil
}

func DecBytes(j any) (Bytes, error) {
	m, _ := j.(map[string]any)
	h, ok := m["hex"].(string)
	if !ok || m["$type"] != "Bytes" {
		return Bytes{}, errors.New("expected Bytes")
	}
	b, err := hex.DecodeString(h)
	if err != nil {
		return Bytes{}, err
	}
	return BytesOf(b), nil
}

func DecUnit(j any) (Unit, error) {
	_, _, err := Untag(j, "Unit")
	return Unit{}, err
}

func DecList[T any](j any, dec func(any) (T, error)) (List[T], error) {
	a, ok := j.([]any)
	if !ok {
		return List[T]{}, errors.New("expected a list")
	}
	s := make([]T, len(a))
	for i, x := range a {
		v, err := dec(x)
		if err != nil {
			return List[T]{}, err
		}
		s[i] = v
	}
	return List[T]{s: s}, nil
}

func DecOption[T any](j any, dec func(any) (T, error)) (Option[T], error) {
	v, p, err := Untag(j, "Option")
	if err != nil {
		return Option[T]{}, err
	}
	switch {
	case v == "Some" && len(p) == 1:
		x, err := dec(p[0])
		return Some(x), err
	case v == "None" && len(p) == 0:
		return None[T](), nil
	}
	return Option[T]{}, errors.New("expected an Option")
}

func DecResult[T, E any](j any, dt func(any) (T, error), de func(any) (E, error)) (Result[T, E], error) {
	v, p, err := Untag(j, "Result")
	if err != nil {
		return Result[T, E]{}, err
	}
	switch {
	case v == "Ok" && len(p) == 1:
		x, err := dt(p[0])
		return Ok[T, E](x), err
	case v == "Err" && len(p) == 1:
		e, err := de(p[0])
		return Err[T](e), err
	}
	return Result[T, E]{}, errors.New("expected a Result")
}

func DecConstraintError(j any) (ConstraintError, error) {
	var out ConstraintError
	if err := ExpectType(j, "ConstraintError"); err != nil {
		return out, err
	}
	t, err := Field(j, "type_name")
	if err != nil {
		return out, err
	}
	m, err := Field(j, "message")
	if err != nil {
		return out, err
	}
	if out.TypeName, err = DecText(t); err != nil {
		return out, err
	}
	out.Message, err = DecText(m)
	return out, err
}

func DecForeignErrorKind(j any) (ForeignErrorKind, error) {
	v, _, err := Untag(j, "std.foreign.ForeignErrorKind")
	if err != nil {
		return 0, err
	}
	for i, n := range foreignErrorKindNames {
		if n == v {
			return ForeignErrorKind(i), nil
		}
	}
	return 0, errors.New("expected a ForeignErrorKind")
}

func DecForeignDetail(j any) (ForeignDetail, error) {
	var out ForeignDetail
	if err := ExpectType(j, "std.foreign.ForeignDetail"); err != nil {
		return out, err
	}
	k, err := Field(j, "key")
	if err != nil {
		return out, err
	}
	v, err := Field(j, "value")
	if err != nil {
		return out, err
	}
	if out.Key, err = DecText(k); err != nil {
		return out, err
	}
	out.Value, err = DecText(v)
	return out, err
}

func DecForeignError(j any) (ForeignError, error) {
	var out ForeignError
	if err := ExpectType(j, "std.foreign.ForeignError"); err != nil {
		return out, err
	}
	k, err := Field(j, "kind")
	if err != nil {
		return out, err
	}
	m, err := Field(j, "message")
	if err != nil {
		return out, err
	}
	d, err := Field(j, "details")
	if err != nil {
		return out, err
	}
	if out.Kind, err = DecForeignErrorKind(k); err != nil {
		return out, err
	}
	if out.Message, err = DecText(m); err != nil {
		return out, err
	}
	out.Details, err = DecList(d, DecForeignDetail)
	return out, err
}

// ===========================================================================
// The JSON driver (spec/hosts.md 4)
// ===========================================================================

// Outside is the driver's answer to an argument outside the function's domain.
func Outside(why string) any { return map[string]any{"outside": why} }

// Answer is the driver's answer of a value.
func Answer(v any) any { return map[string]any{"value": ToJSON(v)} }

// Guard turns a fault of the driver's call into its answer: defer cpl.Guard(cx, &answer).
func Guard(cx *Cx, answer *any) {
	if r := recover(); r != nil {
		f, ok := r.(*Fault)
		if !ok {
			*answer = map[string]any{"panic": fmt.Sprint(r)}
			return
		}
		cx.Attribute(f)
		fault := map[string]any{"code": f.Code, "symbol": f.Symbol}
		if f.ClauseKind != "" {
			fault["clause_kind"] = f.ClauseKind
		}
		*answer = map[string]any{"fault": fault}
	}
}

// Serve answers the driver's requests, one JSON object per line, until the input ends.
func Serve(call func(function string, args []any) any) {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	out := bufio.NewWriter(os.Stdout)
	for {
		line, err := in.ReadString('\n')
		if strings.TrimSpace(line) != "" {
			dec := json.NewDecoder(strings.NewReader(line))
			dec.UseNumber()
			var request map[string]any
			var answer any
			if e := dec.Decode(&request); e != nil {
				answer = Outside(e.Error())
			} else {
				function, _ := request["function"].(string)
				args, _ := request["args"].([]any)
				answer = call(function, args)
			}
			text, e := json.Marshal(answer)
			if e != nil {
				text = []byte(`{"panic":"unencodable answer"}`)
			}
			out.Write(text)
			out.WriteByte('\n')
			out.Flush()
		}
		if err != nil {
			return
		}
	}
}

// ===========================================================================
// The builtins of the standard library (stdlib 1.4-7)
// ===========================================================================

func isWhiteSpace(c rune) bool {
	switch {
	case c >= 0x9 && c <= 0xD, c == 0x20, c == 0x85, c == 0xA0, c == 0x1680,
		c >= 0x2000 && c <= 0x200A, c == 0x2028, c == 0x2029, c == 0x202F, c == 0x205F, c == 0x3000:
		return true
	}
	return false
}

func BytesConcat(a, b Bytes) Bytes { return Bytes{a.s + b.s} }

func Flatten[T any](lists List[List[T]]) List[T] {
	n := 0
	for _, l := range lists.s {
		n += len(l.s)
	}
	s := make([]T, 0, n)
	for _, l := range lists.s {
		s = append(s, l.s...)
	}
	return List[T]{s: s}
}

func IntToText(v Int) string { return v.String() }
func IntAbs(v Int) Int       { return v.Abs() }
func IntMin(a, b Int) Int {
	if b.Lt(a) {
		return b
	}
	return a
}
func IntMax(a, b Int) Int {
	if b.Gt(a) {
		return b
	}
	return a
}
func TextLen(t string) Int              { return I(int64(utf8.RuneCountInString(t))) }
func TextIsEmpty(t string) bool         { return len(t) == 0 }
func BytesLen(b Bytes) Int              { return I(int64(len(b.s))) }
func BytesIsEmpty(b Bytes) bool         { return len(b.s) == 0 }
func ListLen[T any](l List[T]) Int      { return I(int64(len(l.s))) }
func ListIsEmpty[T any](l List[T]) bool { return len(l.s) == 0 }

func count(n Int, length int) int {
	if k, ok := n.index(); ok && k < length {
		return k
	}
	return length
}

func ListTake[T any](l List[T], n Int) List[T] {
	if n.Sign() < 0 {
		panic(requiresFault("n >= 0", "std.prelude.List.take"))
	}
	k := count(n, len(l.s))
	if k == len(l.s) {
		return l
	}
	return List[T]{s: l.s[:k:k]}
}

func ListDrop[T any](l List[T], n Int) List[T] {
	if n.Sign() < 0 {
		panic(requiresFault("n >= 0", "std.prelude.List.drop"))
	}
	k := count(n, len(l.s))
	if k == 0 {
		return l
	}
	return List[T]{s: l.s[k:len(l.s):len(l.s)]}
}

func ListDropLast[T any](l List[T]) List[T] {
	if len(l.s) == 0 {
		return l
	}
	n := len(l.s) - 1
	return List[T]{s: l.s[:n:n]}
}

func ListPush[T any](l List[T], v T) List[T] { return l.Push(v) }

func ListGet[T any](l List[T], i Int) Option[T] {
	if k, ok := i.index(); ok && k < len(l.s) {
		return Some(l.s[k])
	}
	return None[T]()
}

func ListFirst[T any](l List[T]) Option[T] {
	if len(l.s) == 0 {
		return None[T]()
	}
	return Some(l.s[0])
}

func ListLast[T any](l List[T]) Option[T] {
	if len(l.s) == 0 {
		return None[T]()
	}
	return Some(l.s[len(l.s)-1])
}

func ListReverse[T any](l List[T]) List[T] {
	n := len(l.s)
	s := make([]T, n)
	for i, x := range l.s {
		s[n-1-i] = x
	}
	return List[T]{s: s}
}

func ListContains[T any](l List[T], v T) bool {
	for _, x := range l.s {
		if Eq(x, v) {
			return true
		}
	}
	return false
}

func OptionIsSome[T any](o Option[T]) bool { return o.some }
func OptionIsNone[T any](o Option[T]) bool { return !o.some }
func OptionUnwrapOr[T any](o Option[T], d T) T {
	if o.some {
		return o.v
	}
	return d
}
func OptionOkOr[T, E any](o Option[T], e E) Result[T, E] {
	if o.some {
		return Ok[T, E](o.v)
	}
	return Err[T](e)
}
func ResultIsOk[T, E any](r Result[T, E]) bool  { return r.ok }
func ResultIsErr[T, E any](r Result[T, E]) bool { return !r.ok }
func ResultUnwrapOr[T, E any](r Result[T, E], d T) T {
	if r.ok {
		return r.v
	}
	return d
}
func ResultOk[T, E any](r Result[T, E]) Option[T] {
	if r.ok {
		return Some(r.v)
	}
	return None[T]()
}
func ResultErr[T, E any](r Result[T, E]) Option[E] {
	if r.ok {
		return None[E]()
	}
	return Some(r.e)
}

func TextTrim(t string) string        { return strings.TrimFunc(t, isWhiteSpace) }
func TextTrimStart(t string) string   { return strings.TrimLeftFunc(t, isWhiteSpace) }
func TextTrimEnd(t string) string     { return strings.TrimRightFunc(t, isWhiteSpace) }
func TextStartsWith(t, p string) bool { return strings.HasPrefix(t, p) }
func TextEndsWith(t, s string) bool   { return strings.HasSuffix(t, s) }
func TextContains(t, n string) bool   { return strings.Contains(t, n) }

func TextSplit(t, sep string) List[string] {
	if len(sep) == 0 {
		panic(requiresFault("not sep.is_empty()", "std.text.split"))
	}
	return List[string]{s: strings.Split(t, sep)}
}

func TextJoin(parts List[string], sep string) string { return strings.Join(parts.s, sep) }

func TextToUpper(t string) string {
	for i := 0; i < len(t); i++ {
		if c := t[i]; c >= 'a' && c <= 'z' {
			b := []byte(t)
			for j := i; j < len(b); j++ {
				if b[j] >= 'a' && b[j] <= 'z' {
					b[j] -= 'a' - 'A'
				}
			}
			return string(b)
		}
	}
	return t
}

func TextToLower(t string) string {
	for i := 0; i < len(t); i++ {
		if c := t[i]; c >= 'A' && c <= 'Z' {
			b := []byte(t)
			for j := i; j < len(b); j++ {
				if b[j] >= 'A' && b[j] <= 'Z' {
					b[j] += 'a' - 'A'
				}
			}
			return string(b)
		}
	}
	return t
}

func TextParseInt(t string) Result[Int, ConstraintError] {
	if v, ok := ParseInt(t); ok {
		return Ok[Int, ConstraintError](v)
	}
	return Err[Int](ConstraintError{TypeName: "Int", Message: QuoteText(t) + " is not a decimal integer"})
}

func TextFromInt(v Int) string { return v.String() }

func TextChars(t string) List[string] {
	s := make([]string, 0, len(t))
	for i, c := range t {
		s = append(s, t[i:i+utf8.RuneLen(c)])
	}
	return List[string]{s: s}
}

func BytesFromList(values List[Int]) Bytes {
	b := make([]byte, len(values.s))
	for i, v := range values.s {
		x, ok := v.Int64()
		if !ok || x < 0 || x > 255 {
			panic(requiresFault("forall v in values: v >= 0 and v <= 255", "std.bytes.from_list"))
		}
		b[i] = byte(x)
	}
	return Bytes{string(b)}
}

func BytesToList(b Bytes) List[Int] {
	s := make([]Int, len(b.s))
	for i := 0; i < len(b.s); i++ {
		s[i] = I(int64(b.s[i]))
	}
	return List[Int]{s: s}
}

func BytesFromText(t string) Bytes { return Bytes{t} }

func BytesToText(b Bytes) Result[string, ConstraintError] {
	for i := 0; i < len(b.s); {
		c, size := utf8.DecodeRuneInString(b.s[i:])
		if c == utf8.RuneError && size <= 1 {
			return Err[string](ConstraintError{TypeName: "Text", Message: fmt.Sprintf("invalid UTF-8 at byte %d", i)})
		}
		i += size
	}
	return Ok[string, ConstraintError](b.s)
}
